;; Generated by LawSpec. Do not edit.
(ns lawspec.test-runner
  "clojure -M:test: compiles the Java model, runs every test namespace on the
  classpath (or the tests --select ns/prefix names), prints clojure.test's
  report and writes JUnit XML to target/test-results."
  (:require [clojure.java.io :as io]
            [clojure.string :as str]
            [clojure.test :as t]
            [lawspec.build :as build]
            [lawspec.test :as law]))

(defn- namespaces
  "The test namespaces in the classpath's directories: files named *_test.clj."
  []
  (->> (str/split (System/getProperty "java.class.path") (re-pattern (java.io.File/pathSeparator)))
       (map io/file)
       (filter #(.isDirectory ^java.io.File %))
       (mapcat (fn [^java.io.File root]
                 (let [base (count (str (.getCanonicalPath root) "/"))]
                   (for [^java.io.File f (file-seq root)
                         :let [path (.getCanonicalPath f)]
                         :when (str/ends-with? path "_test.clj")]
                     (-> path (subs base (- (count path) 4)) (str/replace "/" ".") (str/replace "_" "-") symbol)))))
       distinct
       sort))

(defn- escape [s]
  (-> (str s) (str/replace "&" "&amp;") (str/replace "<" "&lt;") (str/replace ">" "&gt;") (str/replace "\"" "&quot;")))

(defn- junit [ns-name results]
  (let [cases (sort-by first results)
        count-of (fn [k] (count (filter #(seq (k (second %))) cases)))]
    (str "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n"
         "<testsuite name=\"" (escape ns-name) "\" tests=\"" (count cases) "\" failures=\"" (count-of :failures)
         "\" errors=\"" (count-of :errors) "\" skipped=\"" (count (filter #(:skipped (second %)) cases)) "\">\n"
         (apply str
                (for [[test {:keys [time failures errors skipped]}] cases]
                  (str "  <testcase name=\"" (escape test) "\" classname=\"" (escape ns-name) "\" time=\"" (format "%.3f" (double (or time 0))) "\""
                       (if (or skipped (seq failures) (seq errors))
                         (str ">\n"
                              (when skipped (str "    <skipped message=\"" (escape skipped) "\"/>\n"))
                              (apply str (for [m failures] (str "    <failure message=\"" (escape (:message m)) "\">" (escape (:text m)) "</failure>\n")))
                              (apply str (for [m errors] (str "    <error message=\"" (escape (:message m)) "\">" (escape (:text m)) "</error>\n")))
                              "  </testcase>\n")
                         "/>\n"))))
         "</testsuite>\n")))

(defn- trace [x]
  (if (instance? Throwable x)
    (let [w (java.io.StringWriter.)] (.printStackTrace ^Throwable x (java.io.PrintWriter. w)) (str w))
    (pr-str x)))

(defn- recording [results base]
  (fn [m]
    (let [v (first t/*testing-vars*)
          k (when v [(str (:ns (meta v))) (str (:name (meta v)))])]
      (case (:type m)
        :begin-test-var (swap! results assoc-in [k :start] (System/nanoTime))
        :end-test-var (swap! results update k #(assoc % :time (/ (- (System/nanoTime) (:start % 0)) 1e9)))
        :fail (swap! results update-in [k :failures] conj {:message (:message m) :text (trace (:actual m))})
        :error (swap! results update-in [k :errors] conj {:message (str (:message m) (when (instance? Throwable (:actual m)) (.getMessage ^Throwable (:actual m)))) :text (trace (:actual m))})
        :lawspec/skip (swap! results assoc-in [k :skipped] (:message m))
        nil)
      (base m))))

(defn- selected? [selections exact v]
  (or (and (empty? selections) (empty? exact))
      (let [{:keys [ns name]} (meta v)
            full (str (ns-name ns) "/" name)]
        (or (contains? exact full)
            (some #(str/starts-with? full %) selections)))))

(defn- run-namespace [ns selections exact]
  (let [tests (or (some-> (ns-resolve ns 'lawspec-tests) deref)
                  (->> (ns-interns ns) vals (filter (comp :test meta)) (sort-by (comp str :name meta))))
        schedule (or (some-> (ns-resolve ns 'lawspec-schedule) deref) {})
        chosen (filter #(selected? selections exact %) tests)]
    (when (seq chosen)
      (t/do-report {:type :begin-test-ns :ns (the-ns ns)})
      (law/run (str (ns-name ns)) (vec chosen) schedule)
      (t/do-report {:type :end-test-ns :ns (the-ns ns)}))))

(defn -main [& args]
  (let [selections (->> (partition 2 args) (filter #(= "--select" (first %))) (map second))
        exact (->> (partition 2 args) (filter #(= "--select-exact" (first %))) (map second) set)
        queries (concat selections exact)
        exit (atom 1)]
    (try
      (build/compile-java!)
      (build/use-classes!)
      (let [nss (namespaces)
            nss (if (seq queries) (filter (fn [n] (some #(str/starts-with? % (str n "/")) queries)) nss) nss)
            results (atom {})]
        (doseq [n nss] (require n))
        (binding [t/*report-counters* (ref t/*initial-report-counters*)]
          (binding [t/report (recording results t/report)]
            (doseq [n nss] (run-namespace n selections exact)))
          (let [counters @t/*report-counters*]
            (when (and (seq queries) (zero? (:test counters)))
              (throw (ex-info "The requested selection matched no tests" {:selections queries})))
            (.mkdirs (io/file "target/test-results"))
            (doseq [[ns-name cases] (group-by ffirst (dissoc @results nil))]
              (spit (str "target/test-results/TEST-" ns-name ".xml")
                    (junit ns-name (for [[[_ test] r] cases] [test r]))))
            (t/do-report (assoc counters :type :summary))
            (reset! exit (if (zero? (+ (:fail counters) (:error counters))) 0 1)))))
      (catch Throwable e
        (binding [*out* *err*]
          (println (if (instance? clojure.lang.Compiler$CompilerException e) "Syntax error compiling" "Error:") (.getMessage e))
          (some-> (.getCause e) .getMessage println))
        (reset! exit 1)))
    (shutdown-agents)
    (System/exit @exit)))
